        cookies_data = reponse.get("cookies", {})

        # Ensure cookies are in dictionary format
        if cookies_data is None:
            cookies_data = {}
        if not isinstance(cookies_data, dict):
            raise ValueError("reponse['cookies'] must be a dict if provided.")

        # Update internal cookies state and persist it
        self.cookies = cookies_data
        self._save_cookies()

    def load_cookies(self):
        """
        Loads the cookies from the cookies_file to the cookies data.
        :return: The cookies data, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.load_cookies()
        {'key1': 'value1', 'key2': 'value2'}
        """
        try:
            with open(self.cookies_file, "r", encoding="utf-8") as file:
                data = json.load(file)

            # Handle non-dict JSON gracefully
            if not isinstance(data, dict):
                self.cookies = {}
            else:
                self.cookies = data

        except FileNotFoundError:
            self.cookies = {}
        except json.JSONDecodeError:
            self.cookies = {}
        except OSError:
            self.cookies = {}

