            raise TypeError("plaintext must be a string")
        if not self.key:
            raise ValueError("key must not be empty")
        if not isinstance(self.key, str):
            raise TypeError("key must be a string")

        key_shifts = []
        for k in self.key:
            if k.isalpha():
                key_shifts.append(ord(k.lower()) - ord('a'))

        if not key_shifts:
            raise ValueError("key must contain at least one alphabetic character")

        result = []
        key_idx = 0

        for ch in plaintext:
            if ch.isalpha():
                shift = key_shifts[key_idx % len(key_shifts)]
                if 'a' <= ch <= 'z':
                    result.append(chr((ord(ch) - ord('a') + shift) % 26 + ord('a')))
                else:  # uppercase
                    result.append(chr((ord(ch) - ord('A') + shift) % 26 + ord('A')))
                key_idx += 1
            else:
                # Keep non-alphabetic characters unchanged and do not advance key
                result.append(ch)

        return ''.join(result)

    def rail_fence_cipher(self, plain_text, rails):
        """
        Encrypts the plaintext using the Rail Fence cipher.
        :param plain_text: The plaintext to encrypt, str.
        :param rails: Number of rails to use, int.
        :return: The ciphertext, str.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'
        """
        if not isinstance(plain_text, str):
            raise TypeError("plain_text must be a string")
        if not isinstance(rails, int):
            raise TypeError("rails must be an integer")
        if rails <= 0:
            raise ValueError("rails must be greater than 0")
        if rails == 1 or rails >= len(plain_text):
            return plain_text

        fence = ['' for _ in range(rails)]
        row = 0
        direction = 1  # 1 for down, -1 for up

        for ch in plain_text:
            fence[row] += ch
            if row == 0:
                direction = 1
            elif row == rails - 1:
                direction = -1
            row += direction

        return ''.join(fence)

