class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations,
    including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        # Priority table indexed by operator mapping in compare()
        # index: 0:'+' 1:'-' 2:'*' 3:'/' 4:'(' 5:')' 6:'#' 7:'%'
        self.operat_priority = [0, 3, 2, 1, -1, 1, 0, 2]

    def calculate(self, expression):
        """
        Calculate the result of the given infix expression
        :param expression: string, the infix expression to be calculated
        :return: float, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0
        """
        self.prepare(expression)
        calc_stack = deque()

        for token in self.postfix_stack:
            if not self.is_operator(token):
                calc_stack.append(token)
            else:
                if len(calc_stack) < 2:
                    raise ValueError("Invalid expression")
                second_value = calc_stack.pop()
                first_value = calc_stack.pop()
                result = self._calculate(first_value, second_value, token)
                calc_stack.append(str(result))

        if len(calc_stack) != 1:
            raise ValueError("Invalid expression")

        return float(Decimal(calc_stack.pop()))

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")
        >>> list(expression_calculator.postfix_stack)
        ['2', '3', '4', '*', '+']
        """
        expr = self.transform(expression)
        self.postfix_stack = deque()
        op_stack = deque()
        number_buffer = []

        for ch in expr:
            if ch.isdigit() or ch == '.':
                number_buffer.append(ch)
                continue

            # flush number when operator encountered
            if number_buffer:
                self.postfix_stack.append(''.join(number_buffer))
                number_buffer = []

            if self.is_operator(ch):
                if ch == '(':
                    op_stack.append(ch)
                elif ch == ')':
                    while op_stack and op_stack[-1] != '(':
                        self.postfix_stack.append(op_stack.pop())
                    if not op_stack:
                        raise ValueError("Mismatched parentheses")
                    op_stack.pop()  # pop '('
                else:
                    while (
                        op_stack
                        and op_stack[-1] != '('
                        and self.compare(ch, op_stack[-1])
                    ):
                        self.postfix_stack.append(op_stack.pop())
                    op_stack.append(ch)
            else:
                raise ValueError(f"Invalid character: {ch}")

        if number_buffer:
            self.postfix_stack.append(''.join(number_buffer))

        while op_stack:
            top = op_stack.pop()
            if top in ('(', ')'):
                raise ValueError("Mismatched parentheses")
            self.postfix_stack.append(top)

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        """
        Compare the precedence of two operators.
        Returns True when the operator on stack (peek) should be popped first,
        i.e., when precedence(peek) >= precedence(cur) for left-associative ops.
        :param cur: string, the current operator
        :param peek: string, the operator at the top of the operator stack
        :return: bool
        """
        priority = {
            '+': 1,
            '-': 1,
            '*': 2,
            '/': 2,
            '%': 2,
            '(': 0
        }
        return priority.get(peek, 0) >= priority.get(cur, 0)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: decimal.Decimal, the calculated result
        """
        a = Decimal(str(first_value))
        b = Decimal(str(second_value))

        if current_op == '+':
            return a + b
        if current_op == '-':
            return a - b
        if current_op == '*':
            return a * b
        if current_op == '/':
            if b == 0:
                raise ZeroDivisionError("division by zero")
            return a / b
        if current_op == '%':
            if b == 0:
                raise ZeroDivisionError("modulo by zero")
            return a % b

        raise ValueError(f"Unsupported operator: {current_op}")

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.transform("2 + 3 * 4")
        '2+3*4'
        """
        if expression is None:
            raise ValueError("Expression cannot be None")
        return ''.join(str(expression).split())

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        # No state is needed for this utility class.
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string
        with their corresponding Unicode characters.

        Supports both:
          - Decimal: &#65;
          - Hexadecimal: &#x41; or &#X41;

        Invalid or incomplete entities are left unchanged.

        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """
        if not isinstance(string, str):
            raise TypeError("string must be of type str")

        result = []
        i = 0
        n = len(string)

        while i < n:
            # Potential numeric entity starts with '&#'
            if i + 2 < n and string[i] == '&' and string[i + 1] == '#':
                j = i + 2
                is_hex = False

                # Optional hex marker x/X
                if j < n and string[j] in ('x', 'X'):
                    is_hex = True
                    j += 1

                start_digits = j

                # Collect digits according to mode
                if is_hex:
                    while j < n and self.is_hex_char(string[j]):
                        j += 1
                else:
                    while j < n and string[j].isdigit():
                        j += 1

                # Must have at least one digit and terminate with ';'
                if j > start_digits and j < n and string[j] == ';':
                    num_text = string[start_digits:j]
                    base = 16 if is_hex else 10
                    try:
                        code_point = int(num_text, base)
                        # Valid Unicode range check
                        if 0 <= code_point <= 0x10FFFF:
                            result.append(chr(code_point))
                            i = j + 1
                            continue
                    except (ValueError, OverflowError):
                        pass
                    # If parsing/range fails, fall through and keep original chars unchanged

            # Default: copy one character
            result.append(string[i])
            i += 1

        return ''.join(result)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        return isinstance(char, str) and len(char) == 1 and (
            char.isdigit() or 'a' <= char.lower() <= 'f'
        )
